using System.ComponentModel.DataAnnotations;


namespace NexusCommunication.Models;

/// <summary>A bill generated by the accounts department for one connection. Holds the totals, tax, payments received and the balance still due.</summary>
public class Bill
{
    /// <summary>Primary key.</summary>
    public int Id { get; set; }
    /// <summary>Unique bill number generated by the server (BILL00000001 ...).</summary>
    [MaxLength(20)] public string BillNumber { get; set; } = "";
    /// <summary>Connection this bill belongs to.</summary>
    public int ConnectionId { get; set; }
    /// <summary>Navigation property to the connection.</summary>
    public Connection? Connection { get; set; }
    /// <summary>First day of the billing period.</summary>
    public DateTime PeriodStart { get; set; }
    /// <summary>Last day of the billing period (start + plan validity).</summary>
    public DateTime PeriodEnd { get; set; }
    /// <summary>Date and time the bill was generated.</summary>
    public DateTime BillDate { get; set; } = DateTime.UtcNow;
    /// <summary>Last date for payment without being reported as overdue.</summary>
    public DateTime DueDate { get; set; }
    /// <summary>Total of all charges before discount.</summary>
    public decimal Subtotal { get; set; }
    /// <summary>Bulk / corporate discount deducted from the subtotal.</summary>
    public decimal DiscountAmount { get; set; }
    /// <summary>Subtotal minus discount; the amount on which service tax is charged.</summary>
    public decimal TaxableAmount { get; set; }
    /// <summary>
    /// Service tax rate as a fraction (0.1224 = 12.24%).
    /// Stored with 4 decimals; with the default 2 decimals SQL Server would round 0.1224 to 0.12.
    /// </summary>
   
    public decimal TaxRate { get; set; }
    /// <summary>Service tax charged on the taxable amount.</summary>
    public decimal TaxAmount { get; set; }
    /// <summary>Final amount payable by the customer (taxable amount + tax).</summary>
    public decimal TotalAmount { get; set; }
    /// <summary>Unpaid balance of earlier bills at the time this bill was generated (information only).</summary>
    public decimal PreviousDue { get; set; }
    /// <summary>Total of all payments received against this bill.</summary>
    public decimal AmountPaid { get; set; }
    /// <summary>Amount still unpaid (TotalAmount - AmountPaid).</summary>
    public decimal BalanceDue { get; set; }
    /// <summary>Unpaid, partially paid or paid.</summary>
    public BillStatus Status { get; set; } = BillStatus.Unpaid;
    /// <summary>Employee (accounts department) who generated the bill.</summary>
    public int GeneratedByEmployeeId { get; set; }
    /// <summary>Detailed charge lines printed on the bill.</summary>
    public List<BillLineItem> LineItems { get; set; } = new();
    /// <summary>Payments received against this bill.</summary>
    public List<Payment> Payments { get; set; } = new();
}